1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	
6	const BASE_PREMIUMS: Record<string, number> = {
7	  sword: 100,
8	  amulet: 60,
9	  staff: 80,
10	  potion: 40,
11	  rune: 25,
12	};
13	
14	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
15	// floating-point error that shifts the spec's round-up in MHPCO's favour.
16	const percentOf = (percent: number, amount: number): number => (amount * percent) / 100;
17	
18	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
19	// round up, payouts (MHPCO pays) round down.
20	const roundPremiumInMHPCOsFavour = Math.ceil;
21	
22	export type ScenarioResult = { premium: number };
23	
24	type Item = { type: string };
25	
26	type Scenario = {
27	  steps: { items: Item[] }[];
28	};
29	
30	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
31	
32	const sumBasePremiums = (items: Item[]): number =>
33	  items.reduce((total, item) => total + basePremiumForItem(item), 0);
34	
35	// Only recognises a block when the ENTIRE item list is one: no test yet covers
36	// a block alongside other items, so nothing drives grouping by component type.
37	const itemsFormASingleBlock = (items: Item[]): boolean =>
38	  items.length === BLOCK_SIZE && items.every((item) => item.type === "rune");
39	
40	// A block is a discount on the components' combined base premium, not a flat
41	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
42	// 20 % stays visible as the rule it is.
43	const blockBasePremium = (items: Item[]): number => {
44	  const undiscounted = sumBasePremiums(items);
45	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
46	};
47	
48	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
49	  const [quoteStep] = scenario.steps;
50	  const items = quoteStep.items;
51	  const policyBasePremium = itemsFormASingleBlock(items)
52	    ? blockBasePremium(items)
53	    : sumBasePremiums(items);
54	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
55	  const premium = roundPremiumInMHPCOsFavour(
56	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
57	  );
58	  return { results: [{ premium }] };
59	};
