const policyBasePremiumFor = (items: Item[]): number =>
  itemsFormASingleBlock(items) ? blockBasePremium(items) : sumBasePremiums(items);

const quoteFor = (items: Item[]): ScenarioResult => {
  const policyBasePremium = policyBasePremiumFor(items);
  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
  const premium = roundPremiumInMHPCOsFavour(
    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
  return { premium };
};

// Every scenario so far holds exactly one quote step, so only the first is
// priced. The follow-up-contract discount test will drive priced-per-step.
export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
  const [firstStep] = scenario.steps;
  return { results: [quoteFor(firstStep.items)] };
};
